function valueAfterKSeconds(n, k) {
  const MOD = 1_000_000_007;
  const a = new Array(n).fill(1);
  for (let second = 1; second <= k; second++) {
    for (let i = 1; i < n; i++) {
      a[i] = (a[i] + a[i - 1]) % MOD;
    }
  }
  return a[n - 1];
}

