function valueAfterKSeconds(n, k) {
  // After k seconds the last entry is the binomial coefficient C(n - 1 + k, k); compute it exactly with BigInt.
  let value = 1n;
  for (let j = 1; j <= k; j++) value = value * BigInt(n - 1 + j) / BigInt(j);
  return Number(value % 1000000007n);
}

